-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (업무 통화 표의 줄 수·표 권한·정책·칸 권한 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261025200000' and name='call_personal_box')=1 then '예' else '아니오' end as value
union all select 'personal table present, empty, kind check, one owner policy, RLS on',case when to_regclass('public.app_call_personal') is not null and not exists(select 1 from public.app_call_personal) and exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_call_personal') and conname='app_call_personal_kind_check') and (select count(*) from pg_policy where polrelid=to_regclass('public.app_call_personal') and polroles=array['authenticated'::regrole]::oid[])=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_call_personal'))=1 and exists(select 1 from pg_class where oid=to_regclass('public.app_call_personal') and relrowsecurity and not relforcerowsecurity) then '예' else '아니오' end
union all select 'new columns present on feed items, no default',case when (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and not a.attisdropped and a.attname in('moved_at','refilled_at') and not a.attnotnull and not a.atthasdef)=2 then '예' else '아니오' end
union all select 'source check unchanged (call and telegram only)',case when exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname='app_feed_items_source_check' and pg_get_constraintdef(oid) not like '%call_personal%') then '예' else '아니오' end
union all select 'trigger functions: invoker, empty search_path, no private call, execute revoked from everyone',case when (select count(*) from pg_proc where oid in(to_regprocedure('private.app_call_ref_guard()'),to_regprocedure('private.app_call_personal_guard()'),to_regprocedure('private.app_feed_item_guard()')) and not prosecdef and proconfig=array['search_path=""'] and prosrc not like '%private.%' and coalesce(proacl::text,'')!~'(^|[{,])(anon|authenticated|service_role)?=')=3 then '예' else '아니오' end
union all select 'triggers: feed items two, personal table two',case when (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and not tgisinternal and tgname in('app_feed_items_guard','app_feed_items_call_ref_guard'))=2 and (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and not tgisinternal)=2 and (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_call_personal') and not tgisinternal)=2 then '예' else '아니오' end
union all select 'two new functions: definer, empty search_path, execute only authenticated',case when (select count(*) from pg_proc p where p.oid in(to_regprocedure('public.app_call_move(uuid,text)'),to_regprocedure('public.app_call_work_info(uuid,text,text,uuid)')) and p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=')=2 then '예' else '아니오' end
union all select 'authenticated: personal read plus hide and clear only, feed items unchanged',case when has_table_privilege('authenticated','public.app_call_personal','select') and not has_table_privilege('authenticated','public.app_call_personal','insert') and not has_table_privilege('authenticated','public.app_call_personal','delete') and not has_column_privilege('authenticated','public.app_call_personal','kind','update') and not has_column_privilege('authenticated','public.app_call_personal','title','update') and not has_column_privilege('authenticated','public.app_call_personal','moved_at','update') and not has_table_privilege('authenticated','public.app_feed_items','insert') and not has_table_privilege('authenticated','public.app_feed_items','delete') and not has_column_privilege('authenticated','public.app_feed_items','source','update') and not has_column_privilege('authenticated','public.app_feed_items','moved_at','update') and not has_column_privilege('authenticated','public.app_feed_items','refilled_at','update') then '예' else '아니오' end
union all select 'service_role: personal insert and two read columns only, no new feed write',case when has_column_privilege('service_role','public.app_call_personal','kind','insert') and not has_column_privilege('service_role','public.app_call_personal','moved_at','insert') and not has_column_privilege('service_role','public.app_call_personal','raw_text','select') and not has_any_column_privilege('service_role','public.app_call_personal','update') and not has_table_privilege('service_role','public.app_call_personal','delete') and not has_column_privilege('service_role','public.app_feed_items','moved_at','insert') and not has_column_privilege('service_role','public.app_feed_items','refilled_at','insert') and not has_any_column_privilege('service_role','public.app_feed_items','update') then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege on the two tables',case when not exists(select 1 from pg_class where oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal')) and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal')) and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),''));
